// Merx Studio i18n — vanilla dictionary, PT is the source/fallback language.
// Pattern follows bemerx.com: EN | ES | PT switcher, key-based UI strings.
// User content (project names, messages, code) is never translated here.
export const LOCALE_NAMES = { pt: 'Português', en: 'English', es: 'Español' };
export const SUPPORTED_LOCALES = ['pt', 'en', 'es'];
const STORAGE_KEY = 'merx.studio.locale';

export function detectLocale(navigatorLanguage, stored) {
  if (SUPPORTED_LOCALES.includes(stored)) return stored;
  const lang = String(navigatorLanguage || '').toLowerCase();
  if (lang.startsWith('en')) return 'en';
  if (lang.startsWith('es')) return 'es';
  if (lang.startsWith('pt')) return 'pt';
  return 'pt';
}
export function storedLocale(storage) {
  try { return storage?.getItem(STORAGE_KEY) || null; } catch { return null; }
}
export function persistLocale(storage, locale) {
  try { storage?.setItem(STORAGE_KEY, locale); } catch { /* preference only */ }
}

