let activeLocale = 'pt';
export function getLocale() { return activeLocale; }
export function setLocale(locale) { if (SUPPORTED_LOCALES.includes(locale)) activeLocale = locale; return activeLocale; }
export function initLocale(storage, navigatorLanguage) {
  activeLocale = detectLocale(navigatorLanguage, storedLocale(storage));
  return activeLocale;
}
export function t(key, vars = {}) {
  const raw = LOCALES[activeLocale]?.[key] ?? LOCALES.pt[key] ?? key;
  return String(raw).replace(/\{(\w+)\}/g, (_, name) => vars[name] ?? `{${name}}`);
}
export function localeTag() { return { pt: 'pt-BR', en: 'en-US', es: 'es-ES' }[activeLocale] || 'pt-BR'; }
export function formatDate(value) {
  try { return new Intl.DateTimeFormat(localeTag(), {day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value)); } catch { return String(value ?? ''); }
}
export function formatPrice(amount, currency = 'USD') {
  try { return new Intl.NumberFormat(localeTag(), {style:'currency', currency}).format(amount); } catch { return String(amount); }
}
export function contentFor(kind, id) {
  if (activeLocale === 'pt') return null;
  return CONTENT[kind]?.[activeLocale]?.[id] || null;
}
